def largest_prime_digit_sum(lst):
    """
    You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.

    Args:
        lst (list): A list of integers.

    Returns:
        int: The sum of the digits of the largest prime value in the list.
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    max_prime = 0
    for num in lst:
        if num > 0:  # Ignore non-positive numbers
            if is_prime(num):
                max_prime = max(max_prime, num)

    if max_prime == 0:  # If no prime numbers in the list
        return 0
    else:
        # Convert max_prime to a string to calculate the sum of its digits
        return sum(int(digit) for digit in str(max_prime))
